function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const dateKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=()=>dateKey();
function bank(){return [...(curriculum.showSamples?samples:[]),...custom];}
function streak(){const d=new Date();if(!state.days[dateKey(d)])d.setDate(d.getDate()-1);let n=0;while(state.days[dateKey(d)]){n++;d.setDate(d.getDate()-1);}return n;}
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',4000);}
function navigate(v){if(atlasDispose?.hasUnsaved?.()&&!confirm('저장하지 않은 근육 학습카드가 있습니다. 다른 화면으로 이동할까요?'))return;if(libraryDirty&&view==='manage'&&v!=='manage'&&!confirm('저장하지 않은 변경사항이 있습니다. 나갈까요?'))return;if(v==='manage'&&user?.role==='professor'&&!libraryDraft)libraryDraft={curriculum:structuredClone(curriculum),questions:structuredClone(custom)};if(v==='admin'&&user?.role==='professor'){loadAdmin();}if(['admin','manage'].includes(v)&&user?.role!=='professor')return;if(quiz&&!confirm('진행 중인 레슨을 나갈까요? 완료한 문항의 기록은 유지됩니다.'))return;quiz=null;view=v;render();window.scrollTo(0,0);}
const bodyArt=`<div class="body-art" aria-hidden="true"><svg viewBox="0 0 220 280" fill="none"><ellipse cx="112" cy="57" rx="24" ry="30" fill="#d1ddb9" stroke="#819b68" stroke-width="1.5"/><path d="M103 84v16m18-16v16M103 97l-34 13-22 55-8 43 13 4 17-44 14-28-2 66 13 19-10 59h20l9-58 9 58h20l-10-59 13-19-2-66 14 28 17 44 13-4-8-43-22-55-35-13" fill="#d1ddb9" stroke="#819b68" stroke-width="1.5"/><path d="M113 103v103m-30-88 30 9 29-9m-58 12 29 8 28-8m-57 12 29 7 28-7m-56 12 28 6 27-6m-53 13 26 6 25-6m-51 18 26 11 25-11m-44 30 19 10 18-10M70 118l-15 48-9 38m110-86 16 48 9 38M94 223l-1 57m39-57 1 57" stroke="#8aa271" stroke-width="2"/><path d="M103 113c-13-3-23 8-17 25l17 26m20-51c13-3 23 8 17 25l-17 26" fill="#b9cba1" stroke="#8aa271"/><path d="M112 137c10-14 26-5 14 12l-13 14-9-12c-9-11-2-21 8-14" fill="#8da878"/><circle cx="157" cy="66" r="19" fill="#ffffffb0" stroke="#f9fff2"/><path d="m149 67 6 5 11-13" stroke="#6c8c55" stroke-width="3"/><circle cx="58" cy="223" r="14" fill="#ffffffb0"/><path d="M58 216v14m-7-7h14" stroke="#8ba56b" stroke-width="2"/></svg></div>`;
function heading(label,title,desc){return `<div class="heading"><div><h1>${title}</h1><p>${desc}</p></div><span class="date">${new Date().toLocaleDateString('ko-KR',{month:'long',day:'numeric',weekday:'long'})}</span></div>`;}
function rail(){const n=state.days[today()]||0;const monday=new Date();monday.setDate(monday.getDate()-((monday.getDay()+6)%7));return `<aside class="right-rail"><section class="card"><div class="goal-head"><h3>오늘의 학습 목표</h3><small>하루 5문항</small></div><div class="ring" style="--progress:${Math.min(n/5,1)*100}%"><div><b>${n}<span style="font-size:13px;color:#abb2a4"> / 5</span></b><small>문항 완료</small></div></div><p class="goal-foot">${n>=5?'오늘의 목표 달성! 잘하셨어요. 🌿':'하루 5분, 꾸준함의 힘을 믿어요.'}</p></section><section class="card"><h3>${icon('fire',17)} &nbsp; 차곡차곡 쌓이는 습관</h3><div class="week">${['월','화','수','목','금','토','일'].map((day,i)=>{const d=new Date(monday);d.setDate(d.getDate()+i);const key=dateKey(d);return `<div class="day ${state.days[key]?'done':''} ${key===today()?'today':''}">${day}<span>${state.days[key]?icon('check',12):d.getDate()}</span></div>`;}).join('')}</div><p class="goal-foot">${streak()?`${streak()}일째 배움을 이어가고 있어요.`:'오늘, 첫 번째 기록을 남겨 보세요.'}</p></section><section class="card tip"><h3>✧ &nbsp; 오늘의 작은 학습 팁</h3><p>용어를 외우기 전에 내 몸에서<br>그 위치를 찾아보세요.<br>이름에 위치가 더해지면 오래 기억돼요.</p><small>LEARN A LITTLE, EVERY DAY</small></section></aside>`;}
function review(){const qs=bank().filter(q=>state.mistakes.includes(q.id));return heading('REVIEW & REMEMBER','한 번 더 만나면, 내 지식이 돼요.','틀린 문제를 다시 풀며 헷갈렸던 개념을 차근차근 정리해요.')+(qs.length?`<section class="card"><h3>복습을 기다리는 ${qs.length}문항</h3><p class="muted">정답을 맞히면 오답 목록에서 빠져요. 한 번에 최대 5문항씩 복습합니다.</p><button class="primary" data-review>오답 복습 시작 ${icon('arrow',15)}</button>${qs.map(q=>`<div class="question-row"><div><span class="badge">${esc(units.find(u=>u.id===q.unit)?.name||'이전 단원')}</span><p>${esc(q.question)}</p><small>${esc(q.source)}</small></div></div>`).join('')}</section>`:`<div class="empty">${icon('check',40)}<h3>복습할 오답이 아직 없어요</h3><p>학습 중 틀린 문제가 이곳에 모여요.<br>새로운 레슨을 시작해 볼까요?</p><button class="primary" data-nav="learn">학습하러 가기</button></div>`);}
function progress(){const total=state.answered,accuracy=total?Math.round(state.correct/total*100):0;return heading('GROW AT YOUR OWN PACE','작은 발걸음도, 분명한 성장.','오늘까지 쌓아 온 배움의 기록을 확인해 보세요.')+`<div class="grid-stats"><section class="card"><h3>누적 경험치</h3><b>${state.xp} XP</b><small class="muted">Lv. ${Math.floor(state.xp/100)+1}</small></section><section class="card"><h3>푼 문제</h3><b>${total}문항</b><small class="muted">반복 학습 포함</small></section><section class="card"><h3>정답률</h3><b>${accuracy}%</b><small class="muted">정답 ${state.correct}문항</small></section></div><section class="card"><h3>단원별 학습 기록</h3>${units.map(u=>`<div class="question-row">${icon(u.icon)}<div><p>${esc(u.name)}</p><small>${state.completed[u.id]?'레슨 완료 · '+state.completed[u.id]:'첫 레슨을 기다리고 있어요'}</small></div><span class="badge">${state.completed[u.id]?'완료':'학습 전'}</span></div>`).join('')}</section><section class="card"><h3>최근 완료한 레슨</h3>${state.history.length?state.history.slice(-10).reverse().map(h=>`<div class="question-row"><div><p>${esc(h.title)}</p><small>${esc(h.date)}</small></div><b>${h.correct} / ${h.total}</b></div>`).join(''):'<p class="muted">첫 레슨을 완료하면 기록이 여기에 나타나요.</p>'}</section><div class="actions"><button class="secondary" data-export-progress>학습 기록 내보내기</button></div><p class="hint">${guest?'체험 학습 기록은 저장되지 않습니다. 회원가입 후 기기 간에 학습을 이어갈 수 있어요.':'학습 기록은 계정에 안전하게 저장됩니다. 다른 기기에서도 로그인하면 이어서 학습할 수 있어요.'}</p>`;}
function quizHTML(){const q=quiz.questions[quiz.index];if(quiz.finished)return `<div class="quiz"><section class="quiz-card results"><p class="lesson-context">레슨 완료</p><div class="medal">${icon(quiz.mode==='boss'?'award':'check',42)}</div><h2>${quiz.mode==='boss'?(quiz.correct/quiz.questions.length>=.8?'챕터 마스터 배지를 획득했어요!':'Boss Quiz 도전 완료!'):'오늘도 한 걸음, 잘 해냈어요!'}</h2><p class="muted">${quiz.correct===quiz.questions.length?'모든 문제를 정확하게 풀었어요.':'헷갈린 문제는 오답 복습에서 다시 만나요.'}</p><div class="result-stats"><div><b>${quiz.correct*10}</b><small>획득 XP</small></div><div><b>${quiz.correct}/${quiz.questions.length}</b><small>정답 문항</small></div><div><b>${Math.round(quiz.correct/quiz.questions.length*100)}%</b><small>정답률</small></div></div><div class="actions" style="justify-content:center"><button class="primary" data-finish>학습 여정으로 돌아가기</button>${state.mistakes.length?'<button class="secondary" data-finish-review>오답 확인하기</button>':''}</div></section></div>`;return `<div class="quiz"><div class="quiz-top"><button class="icon-btn" data-exit aria-label="레슨 나가기">${icon('close')}</button><div class="mini-track"><i style="width:${quiz.index/quiz.questions.length*100}%"></i></div><span class="muted">${quiz.index+1} / ${quiz.questions.length}</span></div><section class="quiz-card"><div class="lesson-context">${quiz.review?'REVIEW':esc(quiz.title||units.find(u=>u.id===quiz.unit)?.en||'학습')} &nbsp; · &nbsp; ${q.sample?'체험용 예시':'내 문제은행'}</div><h2>${esc(q.question)}</h2><p class="muted">${quiz.mode==='matching'?'용어에 알맞은 정의를 선택하세요.':'알맞은 답을 하나 선택하세요.'}</p>${q.image?`<img class="question-image" src="${esc(q.image)}" alt="문제 참고 이미지" referrerpolicy="no-referrer">`:''}<div class="options">${q.options.map((o,i)=>`<button class="option ${quiz.selected===i?'selected':''} ${quiz.checked&&i===q.answer?'correct':''} ${quiz.checked&&quiz.selected===i&&i!==q.answer?'wrong':''}" data-option="${i}" ${quiz.checked?'disabled':''} aria-pressed="${quiz.selected===i}"><span>${i+1}</span>${esc(o)}${quiz.checked&&i===q.answer?icon('check',18):''}</button>`).join('')}</div>${quiz.checked?`<div class="feedback ${quiz.selected!==q.answer?'wrong':''}" role="status"><b>${quiz.selected===q.answer?'정답이에요! +10 XP':'괜찮아요. 함께 기억해 봐요.'}</b><p>${quiz.selected!==q.answer?`<b>정답: ${esc(q.options[q.answer])}</b><br>`:''}${esc(q.explanation)}</p><small class="muted">${esc(q.source||'직접 추가한 문제')}</small></div>`:''}<div class="quiz-bottom"><small>서두르지 않아도 괜찮아요.<br>이해하며 한 걸음씩 나아가세요.</small><button class="primary" data-check ${quiz.selected===null?'disabled':''}>${quiz.checked?(quiz.index===quiz.questions.length-1?'레슨 마치기':'다음 문제'): '정답 확인하기'} ${icon('arrow',15)}</button></div></section></div>`;}
function download(name,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function render(){atlasGeneration++;atlasDispose?.();atlasDispose=null;if(booting){app.innerHTML='<div class=boot-screen><span class=brand-mark>'+icon('book',26)+'</span><p>Anatomy Quest</p><small>학습 공간을 준비하고 있어요…</small></div>';return;}if(!user&&!guest){app.innerHTML=authPage();bindAuth();return;}app.innerHTML=frame(quiz?quizHTML():({learn,lessons:learn,review,progress,manage,anatomy:anatomyPage,admin:adminPage}[view]||learn)());bind();bindExtra();bindCourse();if(view==='anatomy'&&!quiz)startAnatomy();}
async function request(path,method='GET',data){const r=await fetch(path,{method,credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:undefined,body:data?JSON.stringify(data):undefined});let d;try{d=await r.json();}catch{throw Error('서버에 연결할 수 없습니다. 잠시 후 다시 시도해 주세요.');}if(!r.ok)throw Object.assign(new Error(d.error||'요청을 처리할 수 없습니다.'),{status:r.status});return d;}
async function boot(){try{const d=await request('/api/me');user=d.user;if(user)await loadAccount();}catch(e){authError=e.message;}finally{booting=false;render();}}
const authArt=`<svg class="auth-art" viewBox="0 0 1400 900" preserveAspectRatio="xMidYMid slice" fill="none" aria-hidden="true"><g stroke="#67d6cf" stroke-opacity=".13" stroke-width="1.4"><circle cx="555" cy="150" r="120"/><circle cx="555" cy="150" r="205"/><circle cx="775" cy="480" r="350"/><ellipse cx="590" cy="470" rx="270" ry="530" transform="rotate(31 590 470)"/><path d="M160 40c80 220-85 180 0 440s-20 190 25 370M190 230c70 0 130 22 180 62m-180-8c60 0 103 20 150 41m-144 3c40 0 87 13 123 35"/><path d="M0 780h180l34-60 28 125 43-84 38 19h430l38-98 30 98h520"/><path d="m90 550 65-50 65 70-63 54-67-74 130 20m690-330 84-80 98 53 99-46"/></g><g fill="#65dad2" fill-opacity=".2"><circle cx="90" cy="550" r="8"/><circle cx="155" cy="500" r="7"/><circle cx="220" cy="570" r="6"/><circle cx="157" cy="624" r="7"/><circle cx="994" cy="160" r="4"/><circle cx="1092" cy="213" r="4"/><circle cx="1191" cy="167" r="4"/></g></svg>`;
const crest=`<svg class="quest-crest" viewBox="0 0 90 90" aria-hidden="true"><circle cx="45" cy="45" r="40" fill="white" stroke="#c5ded8"/><path d="M23 30c-13 17-8 34 9 43M20 39l-6-3m6 12-7 1m11 9-6 5m10 3-3 7m42-43c13 17 8 34-9 43m12-34 6-3m-6 12 7 1m-11 9 6 5m-10 3 3 7" fill="none" stroke="#247e67" stroke-width="3"/><path d="m45 16 18 24-18 11-18-11z" fill="#18806d"/><path d="M27 49c8-3 13-1 18 3 5-4 10-6 18-3v16c-8-3-13-1-18 3-5-4-10-6-18-3z" fill="#174b7c" stroke="white" stroke-width="2"/><path d="M45 52v15M39 30h12m-6-6v13" stroke="white" stroke-width="2"/><text x="45" y="81" text-anchor="middle" fill="#6e8b82" font-size="5" letter-spacing="2">ANATOMY QUEST</text></svg>`;
function authPage(){const signup=authMode==='signup',admin=authTab==='admin';return `<main class="auth-shell"><section class="auth-story"><span class="institution">한서대학교 레저해양스포츠학과</span><h1>우리 몸을 이해하는<br>한 걸음, 한 레슨.</h1><p>골격부터 근육, 신경계까지.<br>문제를 풀고, 해설을 읽고, 3D로 확인하세요.</p><div class="auth-features">${[['chart','단계별 학습','기초부터 한 걸음씩 체계적으로'],['bolt','즉시 해설','정답 근거를 바로 확인'],['check','학습 진도 저장','로그인하면 어느 기기에서든'],['book','교수자 학습 관리','학생별 진도와 성취도 확인']].map(([i,t,d])=>`<div><span>${icon(i,25)}</span><section><b>${t}</b><small>${d}</small></section></div>`).join('')}</div><small class="story-note">하루 한 레슨, 우리 몸을 이해하는 새로운 여정.</small></section><section class="auth-panel"><header class="auth-brand">${crest}<h2>Anatomy <span>Quest</span></h2><p>한서대학교 레저해양스포츠학과 인체해부학 학습 웹앱</p></header><div class="auth-card"><div class="auth-tabs" role="tablist" aria-label="로그인 유형"><button role="tab" aria-selected="${!admin}" data-auth-tab="student" class="${!admin?'active':''}">학생 로그인 ${!admin?'<i></i>':''}</button><button role="tab" aria-selected="${admin}" data-auth-tab="admin" class="${admin?'active':''}">관리자 ${admin?'<i></i>':''}</button></div><h3>${admin?'교수자 관리 공간에 오신 것을 환영합니다':signup?'나만의 해부학 학습을 시작하세요':'인체해부학 학습을 시작하세요'}</h3><p class="auth-desc">${admin?'등록된 교수자만 학생들의 학습 현황을 확인할 수 있어요.':signup?'학습 기록을 저장하고, 어디서든 이어서 배워보세요.':'이름과 비밀번호를 입력해 진행 상황을 이어가세요.'}</p>${authError?`<div class="auth-error" role="alert">${esc(authError)}</div>`:''}${admin?`<div class="admin-auth-info">${icon('chart',26)}<div><b>학생별 진도 · 정답률 · 학습 기록</b><p>교수자 권한은 연결된 ChatGPT 계정으로 확인합니다. 학생 계정으로 관리자 권한을 얻을 수 없습니다.</p></div></div><button class="auth-submit" data-admin-login>교수자 계정으로 로그인 ${icon('arrow',17)}</button><a class="auth-top-link" href="/signin-with-chatgpt?return_to=%2F%3Fadmin%3D1" target="_top">다른 ChatGPT 계정으로 인증하기</a><p class="auth-security">${icon('info',13)} 교수자 계정에만 접근 권한이 부여됩니다.</p>`:`<form id="auth-form"><div class="field"><label for="auth-name">${signup?'이름':'이름 또는 학번'}</label><input id="auth-name" name="name" autocomplete="${signup?'name':'username'}" required maxlength="40" placeholder="${signup?'이름을 입력하세요':'이름 또는 학번을 입력하세요'}"></div>${signup?'<div class="field"><label for="auth-student-no">학번</label><input id="auth-student-no" name="studentNo" autocomplete="off" required pattern="[A-Za-z0-9_-]{3,30}" minlength="3" maxlength="30" placeholder="예: 20260001"><small>같은 이름의 학생을 구분하기 위해 학번을 사용해요.</small></div>':''}<div class="field"><label for="auth-password">비밀번호</label><div class="password-field"><input id="auth-password" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" required ${signup?'minlength="10"':''} maxlength="128" placeholder="${signup?'10자 이상 입력하세요':'비밀번호'}"><button type="button" data-toggle-password aria-label="비밀번호 표시"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/></svg></button></div></div>${signup?'<div class="field"><label for="auth-confirm">비밀번호 확인</label><input id="auth-confirm" name="confirm" type="password" autocomplete="new-password" required minlength="10" maxlength="128" placeholder="비밀번호를 한 번 더 입력하세요"></div><p class="signup-notice">가입하면 교수자가 이름·학번과 학습 기록을 확인할 수 있습니다. 비밀번호는 암호화된 해시로 저장됩니다.</p>':''}<button class="auth-submit" type="submit">${signup?'회원가입하고 시작하기':'로그인'}</button></form><div class="auth-links"><button data-switch-auth>${signup?'이미 계정이 있나요? 로그인':'회원가입'}</button><button data-forgot>비밀번호 찾기?</button></div>`}</div><button class="guest-link" data-guest>로그인 없이 먼저 둘러보기 ${icon('arrow',16)}</button><p class="auth-copyright">Anatomy Quest / 한서대학교</p></section></main>`;}
function bindAuth(){document.querySelectorAll('[data-auth-tab]').forEach(b=>b.onclick=()=>{authTab=b.dataset.authTab;authMode='login';authError='';render();});document.querySelector('[data-switch-auth]')?.addEventListener('click',()=>{authMode=authMode==='signup'?'login':'signup';authError='';render();});document.querySelector('[data-toggle-password]')?.addEventListener('click',e=>{const p=document.querySelector('#auth-password');p.type=p.type==='password'?'text':'password';e.currentTarget.setAttribute('aria-label',p.type==='password'?'비밀번호 표시':'비밀번호 숨기기');e.currentTarget.setAttribute('aria-pressed',p.type==='text');});document.querySelector('[data-forgot]')?.addEventListener('click',()=>toast('교수자에게 학번과 함께 비밀번호 초기화를 요청해 주세요. 교수자 관리 화면에서 초기화할 수 있어요.'));document.querySelector('[data-guest]')?.addEventListener('click',()=>{guest=true;user=null;state=fresh();custom=[];curriculum=structuredClone(defaultCourse);units=courseUnits(curriculum);selectedChapter=curriculum.chapters[0].id;view='learn';authError='';render();});document.querySelector('#auth-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,d=new FormData(form),button=form.querySelector('[type="submit"]');const signup=authMode==='signup';if(signup&&d.get('password')!==d.get('confirm')){authError='비밀번호가 일치하지 않습니다.';document.querySelector('.auth-error')?.remove();form.insertAdjacentHTML('beforebegin',`<div class="auth-error" role="alert">${authError}</div>`);return;}button.disabled=true;button.textContent='연결 중…';try{const result=await request(signup?'/api/register':'/api/login','POST',signup?{name:d.get('name'),studentNo:d.get('studentNo'),password:d.get('password')}:{login:d.get('name'),password:d.get('password')});user=result.user;guest=false;await loadAccount();authError='';render();window.scrollTo(0,0);}catch(err){authError=err.message;user=null;render();}});document.querySelector('[data-admin-login]')?.addEventListener('click',async e=>{e.target.disabled=true;try{const d=await request('/api/admin/login','POST',{});user=d.user;guest=false;await loadAccount();authError='';render();}catch(err){authError=err.message;render();}});}
async function check(){if(!quiz||quiz.selected===null||saving)return;if(guest||user?.role==='professor'){localCheck();return;}if(quiz.checked&&quiz.index<quiz.questions.length-1){quiz.index++;quiz.selected=null;quiz.checked=false;quiz.eventId=crypto.randomUUID();render();return;}const button=document.querySelector('[data-check]');saving=true;button.disabled=true;button.textContent='저장 중…';try{if(!quiz.checked){const q=quiz.questions[quiz.index],d=await request('/api/answer','POST',{questionId:q.id,selected:quiz.selected,eventId:quiz.eventId,...(quiz.mode==='matching'?{kind:'matching',choiceQuestionId:q.choiceIds[quiz.selected]}:{})});state={...fresh(),...d.progress};quiz.checked=true;quiz.eventIds.push(quiz.eventId);if(quiz.selected===q.answer)quiz.correct++;}else{const d=await request('/api/lesson','POST',{eventIds:quiz.eventIds,unit:quiz.unit,review:quiz.review,mode:quiz.mode,chapterId:quiz.chapterId});state={...fresh(),...d.progress};quiz.finished=true;}}catch(e){toast(e.message);}finally{saving=false;render();}}
async function loadAdmin(repaint=true){try{const d=await request('/api/admin/students');adminStudents=d.students;if(repaint&&view==='admin')render();}catch(e){toast(e.message);}}
function adminPage(){const students=adminStudents;const active=students.filter(s=>s.progress.answered>0).length;const avg=students.length&&units.length?Math.round(students.reduce((n,s)=>n+Object.keys(s.progress.completed).length/units.length*100,0)/students.length):0;const q=adminSearch.toLowerCase();const filtered=students.filter(s=>(s.name.toLowerCase().includes(q)||s.student_no.toLowerCase().includes(q))&&(adminFilter==='all'||(adminFilter==='active'?s.progress.answered>0:s.progress.answered===0)));const detail=adminDetail&&students.find(s=>s.id===adminDetail);return heading('PROFESSOR DASHBOARD','학생들의 배움을 한눈에.','학생별 학습 진행 상황과 성취도를 확인하고, 필요한 지도를 이어가세요.')+`<div class="admin-badge">${icon('check',15)} 교수자 전용 · 실제 등록 학생의 기록입니다</div><div class="grid-stats"><section class="card"><h3>등록 학생</h3><b>${students.length}<small>명</small></b></section><section class="card"><h3>학습 시작 학생</h3><b>${active}<small>명</small></b></section><section class="card"><h3>평균 단원 완료율</h3><b>${avg}<small>%</small></b></section></div><section class="card admin-table-card"><div class="admin-toolbar"><div><h3>학생 학습 현황</h3><span class="hint">${filtered.length}명의 학생 · 최근 가입순</span></div><div class="actions"><button class="secondary" data-refresh>새로고침</button><button class="secondary" data-csv>CSV 내보내기</button></div></div><div class="admin-search"><label for="student-search" class="sr-only">이름 또는 학번 검색</label><input id="student-search" placeholder="이름 또는 학번 검색" value="${esc(adminSearch)}"><label for="student-filter" class="sr-only">학습 상태</label><select id="student-filter"><option value="all" ${adminFilter==='all'?'selected':''}>전체 학생</option><option value="active" ${adminFilter==='active'?'selected':''}>학습 시작</option><option value="inactive" ${adminFilter==='inactive'?'selected':''}>학습 전</option></select></div><div class="table-scroll"><table class="students-table"><thead><tr><th>학생</th><th>단원 완료</th><th>푼 문제</th><th>정답률</th><th>경험치</th><th>최근 학습</th><th></th></tr></thead><tbody>${filtered.length?filtered.map(s=>`<tr><td><b>${esc(s.name)}</b><small>${esc(s.student_no)}</small></td><td><b>${Object.keys(s.progress.completed).length} / ${units.length}</b><div class="mini-track"><i style="width:${units.length?Object.keys(s.progress.completed).length/units.length*100:0}%"></i></div></td><td>${s.progress.answered}</td><td>${s.progress.answered?Math.round(s.progress.correct/s.progress.answered*100)+'%':'—'}</td><td>${s.progress.xp} XP</td><td>${s.lastActive?new Date(s.lastActive).toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul'}):'학습 전'}</td><td><button class="secondary" data-student="${esc(s.id)}">상세 보기</button></td></tr>`).join(''):'<tr><td colspan="7" class="table-empty">'+(students.length?'검색 결과가 없습니다.':'아직 가입한 학생이 없습니다. 학생이 회원가입하고 학습하면 이곳에 기록이 표시됩니다.')+'</td></tr>'}</tbody></table></div></section>${detail?`<section class="card" id="student-detail"><div class="admin-toolbar"><div><h3>${esc(detail.name)} 학생의 학습 기록</h3><span class="hint">학번 ${esc(detail.student_no)}</span></div><button class="secondary" data-close-detail>닫기</button></div>${units.map(u=>`<div class="question-row">${icon(u.icon)}<div><p>${esc(u.name)}</p><small>${detail.progress.completed[u.id]?'완료 · '+detail.progress.completed[u.id]:'학습 진행 또는 미시작'}</small></div><span class="badge">${detail.progress.completed[u.id]?'완료':'미완료'}</span></div>`).join('')}<h3 style="margin-top:25px">최근 완료 레슨</h3>${detail.progress.history.length?detail.progress.history.slice(-10).reverse().map(h=>`<div class="question-row"><div><p>${esc(h.title)}</p><small>${esc(h.date)}</small></div><b>${h.correct} / ${h.total}</b></div>`).join(''):'<p class="hint">완료한 레슨이 없습니다.</p>'}<details class="reset-password"><summary>비밀번호 초기화</summary><p class="hint">학생 본인을 확인한 뒤 새 비밀번호를 설정하고 안전한 방법으로 전달하세요. 기존 로그인은 해제됩니다.</p><form id="reset-form"><label for="new-student-password">새 비밀번호 (10자 이상)</label><div class="actions"><input id="new-student-password" type="password" required minlength="10" maxlength="128" autocomplete="new-password"><button class="secondary danger" type="submit">비밀번호 초기화</button></div></form></details></section>`:''}<p class="hint">체험 모드의 기록은 포함되지 않습니다. 정답률과 경험치는 서버에서 실제 응답을 채점해 계산합니다.</p>`;}
function bindExtra(){document.querySelector('[data-logout]')?.addEventListener('click',async()=>{if(atlasDispose?.hasUnsaved?.()&&!confirm('저장하지 않은 근육 학습카드가 있습니다. 로그아웃할까요?'))return;if(libraryDirty&&!confirm('저장하지 않은 변경사항이 있습니다. 로그아웃할까요?'))return;if(quiz&&!confirm('진행 중인 레슨을 나가고 로그아웃할까요?'))return;try{if(user)await request('/api/logout','POST',{});user=null;guest=false;quiz=null;state=fresh();custom=[];libraryDraft=null;libraryDirty=false;authMode='login';authTab='student';authError='';render();}catch(e){toast(e.message);}});document.querySelector('[data-refresh]')?.addEventListener('click',()=>loadAdmin());document.querySelector('#student-search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;adminSearch=e.target.value;render();const input=document.querySelector('#student-search');input.focus();input.setSelectionRange(pos,pos);});document.querySelector('#student-filter')?.addEventListener('change',e=>{adminFilter=e.target.value;render();});document.querySelectorAll('[data-student]').forEach(b=>b.onclick=()=>{adminDetail=b.dataset.student;render();document.querySelector('#student-detail').scrollIntoView({behavior:'smooth',block:'start'});});document.querySelector('[data-close-detail]')?.addEventListener('click',()=>{adminDetail=null;render();});document.querySelector('#reset-form')?.addEventListener('submit',async e=>{e.preventDefault();if(!confirm('학생의 비밀번호를 초기화하고 기존 로그인을 해제할까요?'))return;const button=e.target.querySelector('button');button.disabled=true;try{await request('/api/admin/reset-password','POST',{studentId:adminDetail,password:document.querySelector('#new-student-password').value});toast('비밀번호를 초기화했습니다. 학생에게 새 비밀번호를 전달해 주세요.');e.target.reset();}catch(err){toast(err.message);}finally{button.disabled=false;}});document.querySelector('[data-csv]')?.addEventListener('click',()=>{const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const rows=[['이름','학번','완료 단원','푼 문제','정답률(%)','경험치','최근 학습'],...adminStudents.map(s=>[s.name,s.student_no,Object.keys(s.progress.completed).length,s.progress.answered,s.progress.answered?Math.round(s.progress.correct/s.progress.answered*100):'',s.progress.xp,s.lastActive||''])];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));a.download='학생학습현황-'+today()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});}
if(new URLSearchParams(location.search).has('admin'))authTab='admin';
function validQuestion(q,course=curriculum){return !questionError(q,course);}
function applyLibrary(lib){curriculum=lib.curriculum;units=courseUnits(curriculum);custom=lib.questions||[];libraryRevision=lib.revision??libraryRevision;if(!curriculum.chapters.some(c=>c.id===selectedChapter))selectedChapter=curriculum.chapters[0].id;}
async function loadAccount(){const data=await request('/api/learning');state={...fresh(),...data.progress};applyLibrary(data);selectedChapter=curriculum.chapters[0].id;libraryDraft=null;libraryDirty=false;view=user.role==='professor'?'admin':'learn';if(user.role==='professor')await loadAdmin(false);}
function pct(qs){return qs.length?Math.round(qs.filter(q=>state.mastered.includes(q.id)).length/qs.length*100):0;}
function chapter(){return curriculum.chapters.find(c=>c.id===selectedChapter)||curriculum.chapters[0];}
function chapterQuestions(ch=chapter(),unlocked=false){return bank().filter(q=>ch.units.some(u=>u.id===q.unit&&(!unlocked||u.unlockXp<=state.xp||user?.role==='professor')));}
function unitQuestions(unit){return bank().filter(q=>q.unit===unit);}
function lessonsFor(u){const qs=unitQuestions(u.id),out=[];for(let i=0;i<qs.length;i+=u.lessonSize)out.push(qs.slice(i,i+u.lessonSize));return out;}
function nextUnit(ch=chapter()){return ch.units.find(u=>unitQuestions(u.id).length&&u.unlockXp<=state.xp&&!state.completed[u.id])||ch.units.find(u=>unitQuestions(u.id).length&&u.unlockXp<=state.xp);}
function frame(content){const accuracy=state.answered?Math.round(state.correct/state.answered*100):0;const nav=[['learn','home','홈'],['lessons','book','학습'],['anatomy','muscle','3D 근육'],['review','repeat','오답'],['progress','chart','성장'],...(user?.role==='professor'?[['admin','people','학생'],['manage','folder','문제은행']]:[])];return `<a class="skip-link" href="#learning-content">본문으로 이동</a><div class="quest-layout"><header class="quest-header"><button class="quest-logo" data-nav="learn" aria-label="Anatomy Quest 홈"><span>${icon('book',23)}</span> Anatomy Quest</button><div class="quest-stats"><span class="stat-fire" aria-label="연속 학습 ${streak()}일">${icon('fire',16)} ${streak()}<small>일</small></span><span class="stat-accuracy" aria-label="정답률 ${accuracy}%">${icon('check',16)} ${accuracy}%</span><span class="stat-level">Lv. ${Math.floor(state.xp/100)+1}</span><button class="logout-btn" data-logout>${guest?'로그인':'로그아웃'}</button></div></header><main id="learning-content" tabindex="-1" class="quest-main ${view==='anatomy'?'quest-main-atlas':['admin','manage'].includes(view)?'quest-main-wide':''}">${guest?'<div class="guest-banner">체험 모드입니다. 학습 기록을 저장하려면 로그인하세요.</div>':''}${user?.role==='professor'&&['learn','lessons'].includes(view)?'<div class="guest-banner">교수자 미리보기 · 학습 기록은 학생 진도에 포함되지 않습니다.</div>':''}${content}</main><nav class="quest-bottom" aria-label="주 메뉴">${nav.map(([v,i,t])=>`<button data-nav="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}><span>${icon(i,20)}${v==='review'&&state.mistakes.length?`<b>${state.mistakes.length}</b>`:''}</span><small>${t}</small></button>`).join('')}</nav></div>`;}
function learn(){const ch=chapter(),qs=chapterQuestions(ch),progress=pct(qs),ci=curriculum.chapters.indexOf(ch)+1,next=nextUnit(ch),goals=ch.objectives;return `<section class="welcome-card"><div><h1>${esc(user?.name||'학습자')}님, 오늘도 한 레슨씩.</h1><p>Chapter ${ci} ${esc(ch.name)}<span>오늘의 목표까지 ${Math.max(0,50-(state.dayXp[today()]||0))} XP</span></p></div><div class="welcome-summary"><span><b>${state.correct}<small> / ${state.answered}</small></b>정답 문항</span><span><b>${state.answered?Math.round(state.correct/state.answered*100):0}%</b>정답률</span><span><b>${streak()}<small>일</small></b>연속 학습</span></div><div class="quest-track" aria-label="오늘의 XP 목표 진행률"><i style="width:${Math.min(100,(state.dayXp[today()]||0)/50*100)}%"></i></div></section><div class="learning-workspace"><div class="learning-primary"><section class="continue-learning"><div><h2>${next?'이어서 학습하기':'챕터 살펴보기'}</h2><p>${next?esc(next.name):'학습할 단원과 문제를 확인하세요.'}</p>${next?`<small>${esc(next.en||next.desc)}</small>`:''}</div>${next?`<button class="primary" data-start="${esc(next.id)}">레슨 시작 ${icon('arrow',17)}</button>`:'<button class="primary" data-nav="lessons">단원 보기</button>'}</section><section id="unit-list"><div class="unit-list-title"><h2 class="quest-section-title">학습 단원 <small>${ch.units.length}개</small></h2>${curriculum.showSamples?'<span class="sample-label">체험용 예시 포함</span>':''}</div><div class="chapter-tabs" role="tablist" aria-label="학습 챕터">${curriculum.chapters.map((c,i)=>`<button role="tab" aria-selected="${c.id===ch.id}" data-chapter="${esc(c.id)}" class="${c.id===ch.id?'active':''}">Chapter ${i+1} ${esc(c.name)}</button>`).join('')}</div>${ch.units.length?ch.units.map((u,i)=>{const lessons=lessonsFor(u),questions=unitQuestions(u.id),score=pct(questions),locked=u.unlockXp>state.xp&&user?.role!=='professor',done=lessons.filter(l=>l.every(q=>state.studied.includes(q.id))).length;return `<article class="lesson-unit ${locked?'locked':''}" data-unit-card="${esc(u.id)}"><div class="lesson-unit-head"><span class="lesson-unit-icon tone-${i%6}">${locked?icon('lock'):icon(u.icon||'book')}</span><div><h3>${esc(u.name)}</h3><p>${esc(u.en||u.desc)}</p></div><span class="unit-mastery">${score}%<small>숙련도</small></span></div><div class="lesson-unit-meta">${locked?`잠금 해제 ${u.unlockXp} XP / ${Math.max(0,u.unlockXp-state.xp)} XP 남음`:`레슨 ${done}/${lessons.length} 완료 / ${questions.length}문항`}</div><div class="quest-track"><i style="width:${score}%"></i></div><div class="lesson-buttons">${lessons.length?lessons.map((l,j)=>`<button data-lesson="${esc(u.id)}" data-index="${j}" ${locked?'disabled':''} class="${l.every(q=>state.mastered.includes(q.id))?'done':''}" aria-label="${esc(u.name)} 레슨 ${j+1}${locked?' 잠김':''}">${locked?icon('lock',16):l.every(q=>state.mastered.includes(q.id))?icon('check',16):j+1}</button>`).join(''):`<span class="unit-empty-label">${locked?'잠긴 단원 / ':''}문제 준비중</span>`}${questions.length?`<button class="unit-practice" data-start="${esc(u.id)}" ${locked?'disabled':''} aria-label="${esc(u.name)} 복습">${icon('repeat',17)}</button>`:''}</div></article>`;}).join(''):'<div class="empty"><h3>새로운 단원을 준비하고 있어요</h3><p>교수자가 단원과 문제를 등록하면 여기에 표시됩니다.</p></div>'}</section></div><aside class="learning-secondary" aria-label="실습과 챕터 진도"><button class="atlas-home-entry" data-nav="anatomy"><span>${icon('muscle',28)}</span><div><b>3D 근육 실습실</b><small>형태, 기시와 정지, 신경지배, 동작</small></div><i>${icon('arrow',20)}</i></button><section class="chapter-summary"><h2>Chapter ${ci} ${esc(ch.name)}<small>${esc(ch.subtitle)}</small></h2><p class="chapter-percent"><b>${progress}%</b><small>현재 문제의 정답 숙련도 기준</small></p><div class="quest-track"><i style="width:${progress}%"></i></div><div class="objective-list">${goals.map((g,i)=>{const linked=qs.filter(q=>q.objectiveId===g.id||!q.objectiveId&&(g.unitIds.length?g.unitIds.includes(q.unit):true)),score=pct(linked);return `<div class="objective-row"><div><span><small>학습목표 ${i+1}</small>${esc(g.text)}</span><b>${linked.length?score+'%':'문제 준비중'}</b></div><div class="quest-track"><i style="width:${score}%"></i></div></div>`;}).join('')}</div><span class="boss-badge">${icon('award',16)} ${state.boss[ch.id]>=80?'Chapter Mastered':'Boss Quiz 80% 이상 시 배지 획득'}</span></section></aside></div><section class="mode-section"><h2 class="quest-section-title">학습 방법 선택</h2><div class="mode-grid">${[['lesson','book','학습하기','단원별 순서대로'],['quick','bolt','빠른 복습','현재 챕터 최대 10문항'],['images','image','이미지 퀴즈','그림을 보고 정답 선택'],['matching','link','용어 매칭','용어와 정의를 연결'],['review','repeat','오답 복습','틀린 문제에 집중'],['challenge','target','면과 축 Challenge','면과 축 집중 훈련'],['boss','award',`Chapter ${ci} Boss Quiz`,`최대 20문항 / 최고 ${state.boss[ch.id]||0}% / 80% 이상 배지`]].map(([id,i,title,desc])=>`<button class="mode-card ${id==='boss'?'mode-boss':''}" data-mode="${id}"><span>${icon(i,23)}</span><div><b>${title}</b><small>${desc}</small></div>${icon('arrow',17)}</button>`).join('')}</div></section><p class="quest-footnote">${guest?'체험용 학습입니다. 가입 후 학습 기록을 저장할 수 있어요.':'나만의 속도로, 한 레슨씩. 학습 기록은 계정에 저장됩니다.'}</p>`;}
function openQuiz(qs,config){if(!qs.length)return toast('등록된 문제가 없습니다. 교수자가 문제은행을 등록하면 학습할 수 있어요.');quiz={unit:null,review:false,mode:'lesson',chapterId:chapter().id,title:'학습',questions:qs,index:0,selected:null,checked:false,correct:0,finished:false,eventIds:[],eventId:crypto.randomUUID(),...config};render();window.scrollTo(0,0);}
function start(unit,reviewMode=false,index=null){if(reviewMode){const qs=bank().filter(q=>state.mistakes.includes(q.id)&&units.some(u=>u.id===q.unit&&u.unlockXp<=state.xp)).slice(0,5);return openQuiz(qs,{review:true,title:'오답 복습',mode:'review'});}const u=units.find(u=>u.id===unit);if(!u)return toast('단원을 찾을 수 없습니다. 새로고침해 주세요.');if(u.unlockXp>state.xp&&user?.role!=='professor')return toast(`${u.unlockXp} XP가 필요한 단원입니다.`);const all=lessonsFor(u);let selected=index===null?all.findIndex(l=>!l.every(q=>state.studied.includes(q.id))):index;if(selected<0)selected=0;return openQuiz(all[selected]||[],{unit:u.id,title:u.name,chapterId:u.chapterId});}
function modeStart(mode){const ch=chapter(),qs=chapterQuestions(ch,true);if(mode==='lesson'){const u=nextUnit(ch);return u?start(u.id):document.querySelector('#unit-list')?.scrollIntoView({behavior:'smooth'});}if(mode==='review')return navigate('review');let choices=[...qs];if(mode==='images')choices=choices.filter(q=>q.image);if(mode==='challenge')choices=choices.filter(q=>q.tag==='planes');if(mode==='matching'){const terms=choices.filter(q=>q.term&&q.definition);if(terms.length<2)return toast('용어 매칭을 위해 용어와 정의가 있는 문제를 2개 이상 등록해 주세요.');choices=shuffle(terms).slice(0,10).map(q=>{const options=shuffle([q,...shuffle(terms.filter(t=>t.id!==q.id)).slice(0,3)]);return {...q,question:q.term,options:options.map(t=>t.definition),answer:options.findIndex(t=>t.id===q.id),choiceIds:options.map(t=>t.id)};});}else choices=shuffle(choices).slice(0,mode==='boss'?20:10);if(!choices.length)return toast(mode==='images'?'현재 챕터에 이미지 문제가 없습니다. 문제은행에서 이미지를 추가해 주세요.':mode==='challenge'?'현재 챕터에 면과 축 문제가 없습니다. 문제 유형을 지정하면 이용할 수 있어요.':'학습할 문제가 없습니다.');return openQuiz(choices,{mode,review:true,chapterId:ch.id,title:({quick:'빠른 복습',images:'이미지 퀴즈',matching:'용어 매칭',challenge:'면과 축 Challenge',boss:'Boss Quiz'})[mode]});}
function shuffle(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function localCheck(){if(!quiz||quiz.selected===null)return;if(!quiz.checked){const q=quiz.questions[quiz.index],ok=quiz.selected===q.answer;quiz.checked=true;if(!state.studied.includes(q.id))state.studied.push(q.id);state.answered++;state.days[today()]=(state.days[today()]||0)+1;state.mastered=state.mastered.filter(id=>id!==q.id);if(ok){state.correct++;state.xp+=10;state.dayXp[today()]=(state.dayXp[today()]||0)+10;quiz.correct++;state.mastered.push(q.id);state.mistakes=state.mistakes.filter(id=>id!==q.id);}else if(!state.mistakes.includes(q.id))state.mistakes.push(q.id);}else if(quiz.index<quiz.questions.length-1){quiz.index++;quiz.selected=null;quiz.checked=false;}else{quiz.finished=true;if(quiz.mode==='boss')state.boss[quiz.chapterId]=Math.max(state.boss[quiz.chapterId]||0,Math.round(quiz.correct/quiz.questions.length*100));state.history.push({date:today(),title:quiz.title,correct:quiz.correct,total:quiz.questions.length});state.history=state.history.slice(-100);}for(const u of units){const qs=unitQuestions(u.id);if(qs.length&&qs.every(q=>state.mastered.includes(q.id)))state.completed[u.id]=today();else delete state.completed[u.id];}render();}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{if(b.dataset.nav==='lessons'){navigate('lessons');document.querySelector('#unit-list')?.scrollIntoView({behavior:'smooth'});}else navigate(b.dataset.nav);});document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start));document.querySelector('[data-review]')?.addEventListener('click',()=>start(null,true));document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{quiz.selected=Number(b.dataset.option);render();document.querySelector(`[data-option="${quiz.selected}"]`)?.focus();});document.querySelector('[data-check]')?.addEventListener('click',check);document.querySelector('[data-exit]')?.addEventListener('click',()=>navigate('learn'));document.querySelector('[data-finish]')?.addEventListener('click',()=>{quiz=null;navigate('learn');});document.querySelector('[data-finish-review]')?.addEventListener('click',()=>{quiz=null;navigate('review');});document.querySelector('[data-export-progress]')?.addEventListener('click',()=>download('anatomy-progress-'+today()+'.json',{version:1,progress:state}));}
let courseDialog=null,editorImage='',librarySaving=false;
function draft(){if(!libraryDraft)libraryDraft={curriculum:structuredClone(curriculum),questions:structuredClone(custom)};return libraryDraft;}
function dirty(){libraryDirty=true;const s=document.querySelector('#library-status');if(s){s.textContent='저장하지 않은 변경사항';s.classList.add('unsaved');}document.querySelector('[data-save-library]')?.removeAttribute('disabled');}
function draftCount(id){const d=draft();return d.questions.filter(q=>q.unit===id).length+(d.curriculum.showSamples?samples.filter(q=>q.unit===id).length:0);}
function manage(){const d=draft(),list=courseUnits(d.curriculum);return `<div class="library-editor">${heading('COURSE & QUESTION BANK','나의 강의를, 나의 순서대로.','챕터와 단원을 구성하고 문제를 연결하세요. 저장하면 학생들의 학습 홈에 반영됩니다.')}<div class="library-savebar"><div><b>강의 구성 · 문제은행</b><small id="library-status" class="${libraryDirty?'unsaved':''}">${libraryDirty?'저장하지 않은 변경사항':'모든 변경사항이 저장되어 있습니다'}</small></div><div class="actions"><button class="secondary" data-discard-library>변경 취소</button><button class="primary" data-save-library ${!libraryDirty?'disabled':''}>저장하고 학생 화면에 반영</button></div></div><section class="card library-tools"><div class="admin-toolbar"><div><h3>강의 자료 가져오기 · 내보내기</h3><span class="hint">챕터·단원·학습목표와 문제를 한 파일로 관리할 수 있어요.</span></div><div class="actions"><button class="secondary" data-import>JSON 가져오기</button><button class="secondary" data-export>전체 내보내기</button><button class="secondary" data-template>양식 다운로드</button></div></div><div class="import-target"><label for="import-target">문제만 가져올 때 연결할 단원</label><select id="import-target"><option value="">파일의 단원 정보 유지</option>${list.map(u=>`<option value="${esc(u.id)}">${esc(d.curriculum.chapters.find(c=>c.id===u.chapterId).name)} · ${esc(u.name)}</option>`).join('')}</select></div><input id="import-file" type="file" accept=".json,application/json" hidden><p class="hint">가져온 내용은 먼저 초안에 반영됩니다. 검토 후 위의 저장 버튼을 눌러 주세요. PPT 자동 변환은 아직 연결되지 않았습니다.</p></section><section class="card"><div class="admin-toolbar"><div><h3>챕터 · 단원 구성</h3><span class="hint">${d.curriculum.chapters.length}개 챕터 · ${list.length}개 단원</span></div><button class="secondary" data-add-chapter>＋ 챕터 추가</button></div><label class="sample-toggle"><input id="show-samples" type="checkbox" ${d.curriculum.showSamples?'checked':''}>체험용 예시 25문항을 학생에게 표시</label>${d.curriculum.chapters.map((ch,ci)=>`<section class="course-chapter"><header><div><span>CHAPTER ${ci+1}</span><h3>${esc(ch.name)}</h3><p>${esc(ch.subtitle)}</p></div><div class="tiny-actions"><button data-chapter-move="${esc(ch.id)}" data-delta="-1" ${ci===0?'disabled':''} aria-label="${esc(ch.name)} 챕터 위로">↑</button><button data-chapter-move="${esc(ch.id)}" data-delta="1" ${ci===d.curriculum.chapters.length-1?'disabled':''} aria-label="${esc(ch.name)} 챕터 아래로">↓</button><button data-edit-chapter="${esc(ch.id)}">수정</button><button class="danger" data-delete-chapter="${esc(ch.id)}">삭제</button></div></header><div class="course-objectives"><div><b>학습목표 ${ch.objectives.length}개</b><button data-edit-goals="${esc(ch.id)}">학습목표 편집</button></div>${ch.objectives.length?ch.objectives.map((g,i)=>`<p>${i+1}. ${esc(g.text)}</p>`).join(''):'<p>아직 등록한 학습목표가 없습니다.</p>'}</div><div>${ch.units.map((u,ui)=>`<div class="course-unit-row"><span class="course-unit-number">${ui+1}</span><span>${esc(u.emoji)}</span><div class="course-unit-copy"><b>${esc(u.name)}</b><small>${draftCount(u.id)}문항 · 레슨당 ${u.lessonSize}문항 · ${u.unlockXp?u.unlockXp+' XP 해제':'잠금 없음'}</small></div><div class="tiny-actions"><button data-unit-move="${esc(u.id)}" data-delta="-1" ${ui===0?'disabled':''} aria-label="${esc(u.name)} 위로">↑</button><button data-unit-move="${esc(u.id)}" data-delta="1" ${ui===ch.units.length-1?'disabled':''} aria-label="${esc(u.name)} 아래로">↓</button><button data-edit-unit="${esc(u.id)}">수정</button><button class="danger" data-delete-unit="${esc(u.id)}">삭제</button></div></div>`).join('')}</div><button class="add-unit" data-add-unit="${esc(ch.id)}">＋ 이 챕터에 단원 추가</button></section>`).join('')}</section><section class="card"><div class="admin-toolbar"><div><h3>문제은행 (${d.questions.length}문항)</h3><span class="hint">문항을 편집하면서 연결 단원과 학습목표도 바꿀 수 있어요.</span></div><button class="primary" data-add-question ${!list.length?'disabled':''}>＋ 새 문제</button></div>${d.questions.length?d.questions.map(q=>`<div class="question-row"><div><span class="badge">${esc(list.find(u=>u.id===q.unit)?.name||'연결 단원 없음')}</span>${q.image?' <span class="badge">이미지</span>':''}${q.term&&q.definition?' <span class="badge">용어 매칭</span>':''}<p>${esc(q.question)}</p><small>정답: ${esc(q.options[q.answer])} · ${esc(q.source||'출처 미입력')}</small></div><div class="tiny-actions"><button data-edit-question="${esc(q.id)}">수정</button><button class="danger" data-delete-question="${esc(q.id)}">삭제</button></div></div>`).join(''):'<div class="bank-empty"><span>📚</span><p>강의에 맞는 첫 문제를 추가해 보세요.</p><small>단원을 먼저 구성한 뒤, 직접 입력하거나 JSON 파일로 가져올 수 있어요.</small></div>'}</section>${courseDialog?dialogHTML():''}</div>`;}
function modalOpen(kind,data={}){courseDialog={kind,...data};if(kind==='question')editorImage=draft().questions.find(q=>q.id===data.id)?.image||'';render();}
function dialogHTML(){const d=draft(),x=courseDialog,ch=d.curriculum.chapters.find(c=>c.id===x.chapterId),all=courseUnits(d.curriculum);let body='',title='';if(x.kind==='chapter'){const c=ch||{name:'',subtitle:''};title=ch?'챕터 수정':'새 챕터';body=`<div class="field"><label for="chapter-name">챕터 이름</label><input id="chapter-name" name="name" required maxlength="150" value="${esc(c.name)}" placeholder="예: 신경계통"></div><div class="field"><label for="chapter-subtitle">영문명 또는 부제</label><input id="chapter-subtitle" name="subtitle" maxlength="250" value="${esc(c.subtitle)}" placeholder="Nervous System"></div>`;}if(x.kind==='unit'){const u=all.find(u=>u.id===x.id)||{name:'',en:'',desc:'',emoji:'📖',unlockXp:0,lessonSize:5,chapterId:x.chapterId};title=x.id?'단원 수정':'새 단원';body=`<div class="field"><label for="unit-chapter">챕터</label><select id="unit-chapter" name="chapterId">${d.curriculum.chapters.map(c=>`<option value="${esc(c.id)}" ${c.id===u.chapterId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label for="unit-name">단원 이름</label><input id="unit-name" name="name" required maxlength="150" value="${esc(u.name)}"></div><div class="field"><label for="unit-en">영문명 또는 부제</label><input id="unit-en" name="en" maxlength="250" value="${esc(u.en)}"></div><div class="field"><label for="unit-desc">단원 설명</label><input id="unit-desc" name="desc" maxlength="600" value="${esc(u.desc)}"></div><div class="form-grid"><div class="field"><label for="unit-emoji">아이콘</label><select id="unit-emoji" name="emoji">${['📖','🧬','🔬','🧩','🫀','🧍','🎯','🦴','💪','🧠','❤️','🫁','💡','🧪'].map(e=>`<option ${u.emoji===e?'selected':''}>${e}</option>`).join('')}</select></div><div class="field"><label for="unit-size">레슨당 문항 수</label><input id="unit-size" name="lessonSize" type="number" min="1" max="10" required value="${u.lessonSize}"></div><div class="field full"><label for="unit-xp">잠금 해제 XP (0이면 바로 학습)</label><input id="unit-xp" name="unlockXp" type="number" min="0" max="1000000" required value="${u.unlockXp}"></div></div><p class="hint">단원 이름과 순서를 바꿔도 학생의 기존 문항별 학습 기록은 유지됩니다.</p>`;}if(x.kind==='goals'){title='학습목표 편집';body=`<p class="hint">목표마다 연결 단원을 선택하세요. 문항에도 목표를 직접 연결할 수 있습니다.</p><div id="goal-edit-rows">${x.goals.map((g,i)=>goalRow(g,i,ch)).join('')}</div><button class="secondary" type="button" data-add-goal>＋ 학습목표 추가</button>`;}if(x.kind==='question'){const q=d.questions.find(q=>q.id===x.id)||{unit:all[0]?.id||'',question:'',options:['','','',''],answer:0,explanation:'',source:'',objectiveId:'',tag:'',term:'',definition:''};const target=d.curriculum.chapters.find(c=>c.units.some(u=>u.id===q.unit));title=x.id?'문제 수정':'새 문제 추가';body=`<div class="form-grid"><div class="field"><label for="q-unit">연결 단원</label><select id="q-unit" name="unit">${all.map(u=>`<option value="${esc(u.id)}" ${u.id===q.unit?'selected':''}>${esc(d.curriculum.chapters.find(c=>c.id===u.chapterId).name)} · ${esc(u.name)}</option>`).join('')}</select></div><div class="field"><label for="q-goal">학습목표 (선택)</label><select id="q-goal" name="objectiveId">${goalOptions(target,q.objectiveId)}</select></div><div class="field full"><label for="q-question">문제</label><textarea id="q-question" name="question" required maxlength="2000" rows="3">${esc(q.question)}</textarea></div>${q.options.map((o,i)=>`<div class="field"><label for="q-o${i}">선택지 ${i+1}</label><input id="q-o${i}" name="o${i}" required maxlength="1000" value="${esc(o)}"></div>`).join('')}<div class="field"><label for="q-answer">정답</label><select id="q-answer" name="answer">${[0,1,2,3].map(i=>`<option value="${i}" ${q.answer===i?'selected':''}>선택지 ${i+1}</option>`).join('')}</select></div><div class="field"><label for="q-tag">집중 훈련 유형</label><select id="q-tag" name="tag"><option value="">일반 문제</option><option value="planes" ${q.tag==='planes'?'selected':''}>면과 축 Challenge</option></select></div><div class="field full"><label for="q-explanation">해설</label><textarea id="q-explanation" name="explanation" required maxlength="5000" rows="3">${esc(q.explanation)}</textarea></div><div class="field full"><label for="q-source">출처 (선택)</label><input id="q-source" name="source" maxlength="300" value="${esc(q.source)}" placeholder="예: 강의.pptx · 슬라이드 12"></div></div><details class="question-extras" ${q.image||q.term?'open':''}><summary>이미지 · 용어 매칭 추가 (선택)</summary><div class="field"><label for="q-image-url">이미지 HTTPS 주소</label><input id="q-image-url" name="image" maxlength="2000" value="${editorImage.startsWith('https:')?esc(editorImage):''}" placeholder="https://…"><span class="hint">또는 PNG/JPEG/WebP 파일을 등록하세요. (500KB 이하)</span><input id="q-image-file" type="file" accept="image/png,image/jpeg,image/webp"><div id="image-edit-preview">${editorImage?`<img src="${esc(editorImage)}" alt="문제 이미지 미리보기" referrerpolicy="no-referrer"><button type="button" class="secondary" data-clear-image>이미지 제거</button>`:''}</div></div><div class="field"><label for="q-term">용어 매칭: 용어</label><input id="q-term" name="term" maxlength="200" value="${esc(q.term)}" placeholder="예: 시상면 (Sagittal plane)"></div><div class="field"><label for="q-definition">용어 매칭: 정의</label><textarea id="q-definition" name="definition" maxlength="1000" rows="2">${esc(q.definition)}</textarea></div></details>`;}return `<dialog id="course-dialog" class="course-dialog" aria-labelledby="dialog-title"><div class="dialog-header"><h2 id="dialog-title">${title}</h2><button type="button" class="icon-btn" data-close-dialog aria-label="닫기">${icon('close',20)}</button></div><form id="course-dialog-form"><div id="dialog-error" class="auth-error" role="alert" hidden></div>${body}<footer><button type="button" class="secondary" data-close-dialog>취소</button><button type="submit" class="primary">초안에 반영</button></footer></form></dialog>`;}
function goalOptions(ch,selected=''){return '<option value="">단원 기준으로 계산</option>'+(ch?.objectives||[]).map(g=>`<option value="${esc(g.id)}" ${g.id===selected?'selected':''}>${esc(g.text)}</option>`).join('');}
function goalRow(g,i,ch){return `<div class="goal-edit-row" data-goal-id="${esc(g.id)}"><div class="field"><label for="goal-text-${i}">학습목표 ${i+1}</label><textarea id="goal-text-${i}" data-goal-text required maxlength="500" rows="2">${esc(g.text)}</textarea></div><span class="goal-unit-label">연결 단원 (선택하지 않으면 챕터 전체)</span><div class="goal-unit-checks">${ch.units.map(u=>`<label><input type="checkbox" data-goal-unit value="${esc(u.id)}" ${g.unitIds.includes(u.id)?'checked':''}>${esc(u.name)}</label>`).join('')}</div><button type="button" class="secondary danger" data-remove-goal>삭제</button></div>`;}
function closeCourseDialog(){courseDialog=null;render();}
async function saveLibrary(){if(librarySaving)return;const d=draft(),error=libraryError(d.curriculum,d.questions,samples);if(error)return toast(error);librarySaving=true;document.querySelectorAll('.library-editor button,.library-editor input,.library-editor select').forEach(e=>e.disabled=true);try{const result=await request('/api/library','PUT',{...d,revision:libraryRevision});applyLibrary(result);libraryDraft=structuredClone({curriculum,questions:custom});libraryDirty=false;toast('저장했습니다. 학생들의 학습 화면에 반영됩니다.');}catch(e){toast('저장하지 못했습니다: '+e.message);}finally{librarySaving=false;render();}}
function bindCourse(){document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>{selectedChapter=b.dataset.chapter;render();});document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>start(b.dataset.lesson,false,Number(b.dataset.index)));document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>modeStart(b.dataset.mode));if(view!=='manage'||user?.role!=='professor')return;const d=draft();document.querySelector('[data-save-library]')?.addEventListener('click',saveLibrary);document.querySelector('[data-discard-library]')?.addEventListener('click',()=>{if(!libraryDirty||confirm('저장하지 않은 변경사항을 취소할까요?')){libraryDraft=null;libraryDirty=false;courseDialog=null;render();}});document.querySelector('#show-samples')?.addEventListener('change',e=>{d.curriculum.showSamples=e.target.checked;const error=libraryError(d.curriculum,d.questions,samples);if(error){d.curriculum.showSamples=!e.target.checked;toast(error);render();return;}dirty();render();});document.querySelector('[data-add-chapter]')?.addEventListener('click',()=>modalOpen('chapter'));document.querySelectorAll('[data-edit-chapter]').forEach(b=>b.onclick=()=>modalOpen('chapter',{chapterId:b.dataset.editChapter}));document.querySelectorAll('[data-add-unit]').forEach(b=>b.onclick=()=>modalOpen('unit',{chapterId:b.dataset.addUnit}));document.querySelectorAll('[data-edit-unit]').forEach(b=>b.onclick=()=>modalOpen('unit',{id:b.dataset.editUnit}));document.querySelectorAll('[data-edit-goals]').forEach(b=>b.onclick=()=>{const ch=d.curriculum.chapters.find(c=>c.id===b.dataset.editGoals);modalOpen('goals',{chapterId:ch.id,goals:structuredClone(ch.objectives)});});document.querySelectorAll('[data-chapter-move]').forEach(b=>b.onclick=()=>{const a=d.curriculum.chapters,i=a.findIndex(c=>c.id===b.dataset.chapterMove),j=i+Number(b.dataset.delta);if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];dirty();render();});document.querySelectorAll('[data-unit-move]').forEach(b=>b.onclick=()=>{const ch=d.curriculum.chapters.find(c=>c.units.some(u=>u.id===b.dataset.unitMove)),i=ch.units.findIndex(u=>u.id===b.dataset.unitMove),j=i+Number(b.dataset.delta);if(j<0||j>=ch.units.length)return;[ch.units[i],ch.units[j]]=[ch.units[j],ch.units[i]];dirty();render();});document.querySelectorAll('[data-delete-unit]').forEach(b=>b.onclick=()=>{const id=b.dataset.deleteUnit;if(draftCount(id))return toast('연결된 문제가 있습니다. 문제를 다른 단원으로 옮기거나 삭제한 뒤 단원을 삭제해 주세요.');if(!confirm('이 단원을 삭제할까요? 기존 학생의 문항별 학습 기록은 유지됩니다.'))return;for(const ch of d.curriculum.chapters){ch.units=ch.units.filter(u=>u.id!==id);ch.objectives.forEach(g=>g.unitIds=g.unitIds.filter(x=>x!==id));}dirty();render();});document.querySelectorAll('[data-delete-chapter]').forEach(b=>b.onclick=()=>{const ch=d.curriculum.chapters.find(c=>c.id===b.dataset.deleteChapter);if(d.curriculum.chapters.length===1)return toast('최소 한 개의 챕터를 유지해 주세요.');if(ch.units.some(u=>draftCount(u.id)))return toast('챕터 안에 문제가 연결된 단원이 있습니다. 문제를 먼저 옮겨 주세요.');if(!confirm('챕터와 안의 빈 단원을 삭제할까요?'))return;d.curriculum.chapters=d.curriculum.chapters.filter(c=>c.id!==ch.id);dirty();render();});document.querySelector('[data-add-question]')?.addEventListener('click',()=>modalOpen('question'));document.querySelectorAll('[data-edit-question]').forEach(b=>b.onclick=()=>modalOpen('question',{id:b.dataset.editQuestion}));document.querySelectorAll('[data-delete-question]').forEach(b=>b.onclick=()=>{if(!confirm('이 문제를 문제은행에서 삭제할까요? 저장 전에는 학생 화면이 바뀌지 않습니다.'))return;d.questions=d.questions.filter(q=>q.id!==b.dataset.deleteQuestion);dirty();render();});document.querySelector('[data-export]')?.addEventListener('click',()=>download('anatomy-course-'+today()+'.json',{version:2,...d}));document.querySelector('[data-template]')?.addEventListener('click',()=>{const u=courseUnits(d.curriculum)[0];download('anatomy-course-template.json',{version:2,curriculum:d.curriculum,questions:u?[{id:'my-question-1',unit:u.id,question:'문제를 입력하세요',options:['선택지 1','선택지 2','선택지 3','선택지 4'],answer:0,explanation:'정답 근거를 입력하세요',source:'강의.pptx · 슬라이드 1',term:'',definition:'',objectiveId:'',tag:''}]:[]});});document.querySelector('[data-import]')?.addEventListener('click',()=>document.querySelector('#import-file').click());document.querySelector('#import-file')?.addEventListener('change',importLibrary);const dialog=document.querySelector('#course-dialog');if(!dialog)return;dialog.showModal();dialog.addEventListener('cancel',e=>{e.preventDefault();closeCourseDialog();});document.querySelectorAll('[data-close-dialog]').forEach(b=>b.onclick=closeCourseDialog);document.querySelector('#q-unit')?.addEventListener('change',e=>{const ch=d.curriculum.chapters.find(c=>c.units.some(u=>u.id===e.target.value));document.querySelector('#q-goal').innerHTML=goalOptions(ch);});document.querySelector('#q-image-file')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>500000||!['image/png','image/jpeg','image/webp'].includes(file.type))return toast('500KB 이하의 PNG/JPEG/WebP 파일을 선택해 주세요.');const reader=new FileReader();reader.onload=()=>{editorImage=reader.result;document.querySelector('#q-image-url').value='';document.querySelector('#image-edit-preview').innerHTML=`<img src="${esc(editorImage)}" alt="문제 이미지 미리보기"><button type="button" class="secondary" data-clear-image>이미지 제거</button>`;bindClearImage();};reader.readAsDataURL(file);});document.querySelector('#q-image-url')?.addEventListener('input',e=>{editorImage=e.target.value.trim();});bindClearImage();document.querySelector('[data-add-goal]')?.addEventListener('click',()=>{const rows=document.querySelector('#goal-edit-rows');if(rows.children.length>=20)return toast('학습목표는 챕터당 20개까지 등록할 수 있어요.');const ch=d.curriculum.chapters.find(c=>c.id===courseDialog.chapterId),i=Date.now();rows.insertAdjacentHTML('beforeend',goalRow({id:'goal-'+crypto.randomUUID(),text:'',unitIds:[]},i,ch));bindRemoveGoals();});bindRemoveGoals();document.querySelector('#course-dialog-form')?.addEventListener('submit',submitCourseDialog);}
function bindClearImage(){document.querySelector('[data-clear-image]')?.addEventListener('click',()=>{editorImage='';document.querySelector('#q-image-url').value='';document.querySelector('#q-image-file').value='';document.querySelector('#image-edit-preview').innerHTML='';});}
function bindRemoveGoals(){document.querySelectorAll('[data-remove-goal]').forEach(b=>b.onclick=()=>b.closest('.goal-edit-row').remove());}
function submitCourseDialog(e){e.preventDefault();const d=draft(),data=new FormData(e.target),x=courseDialog,next=structuredClone(d);try{if(x.kind==='chapter'){const ch=next.curriculum.chapters.find(c=>c.id===x.chapterId);if(ch){ch.name=data.get('name').trim();ch.subtitle=data.get('subtitle').trim();}else next.curriculum.chapters.push({id:'chapter-'+crypto.randomUUID(),name:data.get('name').trim(),subtitle:data.get('subtitle').trim(),units:[],objectives:[]});}if(x.kind==='unit'){let existing=courseUnits(next.curriculum).find(u=>u.id===x.id);const u={id:existing?.id||'unit-'+crypto.randomUUID(),name:data.get('name').trim(),en:data.get('en').trim(),desc:data.get('desc').trim(),emoji:data.get('emoji'),icon:existing?.icon||'book',unlockXp:Number(data.get('unlockXp')),lessonSize:Number(data.get('lessonSize'))};const target=next.curriculum.chapters.find(c=>c.id===data.get('chapterId'));if(existing){const old=next.curriculum.chapters.find(c=>c.units.some(u=>u.id===x.id)),index=old.units.findIndex(u=>u.id===x.id);if(old.id===target.id)old.units[index]=u;else{old.units.splice(index,1);old.objectives.forEach(g=>g.unitIds=g.unitIds.filter(id=>id!==u.id));target.units.push(u);next.questions.filter(q=>q.unit===u.id).forEach(q=>q.objectiveId='');}}else target.units.push(u);}if(x.kind==='goals'){const ch=next.curriculum.chapters.find(c=>c.id===x.chapterId);ch.objectives=Array.from(document.querySelectorAll('.goal-edit-row')).map(row=>{const ids=Array.from(row.querySelectorAll('[data-goal-unit]:checked')).map(input=>input.value);return {id:row.dataset.goalId,text:row.querySelector('[data-goal-text]').value.trim(),unitIds:ids};});for(const q of next.questions.filter(q=>ch.units.some(u=>u.id===q.unit)))if(q.objectiveId&&!ch.objectives.some(g=>g.id===q.objectiveId))q.objectiveId='';}if(x.kind==='question'){const q={id:x.id||'question-'+crypto.randomUUID(),unit:data.get('unit'),question:data.get('question').trim(),options:[0,1,2,3].map(i=>data.get('o'+i).trim()),answer:Number(data.get('answer')),explanation:data.get('explanation').trim(),source:data.get('source').trim(),objectiveId:data.get('objectiveId'),tag:data.get('tag'),term:data.get('term')?.trim()||'',definition:data.get('definition')?.trim()||'',sample:false};if(editorImage)q.image=editorImage;if(Boolean(q.term)!==Boolean(q.definition))throw Error('용어 매칭을 사용하려면 용어와 정의를 모두 입력해 주세요.');const i=next.questions.findIndex(q=>q.id===x.id);if(i>=0)next.questions[i]=q;else next.questions.push(q);}const error=libraryError(next.curriculum,next.questions,samples);if(error)throw Error(error);libraryDraft=next;dirty();courseDialog=null;render();}catch(err){const el=document.querySelector('#dialog-error');el.hidden=false;el.textContent=err.message;el.scrollIntoView({block:'nearest'});}}
async function importLibrary(e){const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('2MB 이하의 JSON 파일을 선택해 주세요.');const data=JSON.parse(await file.text()),d=draft();let next;if(data.curriculum){next={curriculum:data.curriculum,questions:data.questions};}else{const qs=Array.isArray(data)?data:data.questions;if(!Array.isArray(qs))throw Error('questions 배열 또는 강의 구성이 있는 JSON 파일이 필요합니다.');const target=document.querySelector('#import-target').value,used=new Set(d.questions.map(q=>q.id));next=structuredClone(d);for(const q of qs){if(!q||typeof q!=='object')throw Error('문제 형식을 확인해 주세요.');const added={...q,sample:false};if(target){added.unit=target;added.objectiveId='';}if(!added.id)added.id='question-'+crypto.randomUUID();if(!used.has(added.id)){next.questions.push(added);used.add(added.id);}}}const error=libraryError(next.curriculum,next.questions,samples);if(error)throw Error(error);libraryDraft=next;libraryDirty=true;courseDialog=null;render();toast('가져온 내용을 초안에 반영했어요. 검토 후 저장해 주세요.');}catch(err){toast(err.message||'파일을 읽지 못했습니다.');}finally{e.target.value='';}}
window.addEventListener('beforeunload',e=>{if(libraryDirty||atlasDispose?.hasUnsaved?.()){e.preventDefault();e.returnValue='';}});
document.addEventListener('visibilitychange',async()=>{if(document.visibilityState!=='visible'||!user||quiz||libraryDirty||view==='anatomy')return;try{const course=await request('/api/course');if(course.revision!==libraryRevision){const latest=await request('/api/learning');applyLibrary(latest);state={...fresh(),...latest.progress};libraryDraft=null;render();toast('교수자가 수정한 강의 내용을 반영했습니다.');}}catch{}});
boot();

function anatomyPage(){return '<div id="muscle-atlas"><div class="atlas-starting" role="status">3D 학습 실습실을 불러오고 있어요…</div></div>';}
async function startAnatomy(){const generation=atlasGeneration;try{const module=await import('/anatomy.bundle.js');if(generation!==atlasGeneration||view!=='anatomy'||quiz)return;atlasDispose=module.mountMuscleAtlas(document.querySelector('#muscle-atlas'),{professor:user?.role==='professor',request,guest});}catch(e){if(generation!==atlasGeneration)return;const root=document.querySelector('#muscle-atlas');if(root){root.innerHTML='<div class="empty"><h3>3D 실습실을 불러오지 못했습니다</h3><p>잠시 후 메뉴를 다시 열어 주세요.</p><button class="secondary" data-retry-atlas>다시 시도</button></div>';root.querySelector('button').onclick=()=>render();}}}
